            (value as UserReadMinimal) || undefined;
          break;
        case "created_date":
          if (
            value &&
            typeof value === "object" &&
            "from" in value &&
            "to" in value
          ) {
            const dateRange = value as FilterDateRange;
            updates.dateFrom = dateRange.from?.toISOString();
