arguments.newString:
clearError();
const newEncounter = { ...encounter, ...updates };
const encounterClass = encounterData?.encounter_class;
// Only normalize hospitalization once the encounter (and thus its class) has
// loaded. Before that, encounterClass is undefined and we must not clobber
// the seeded hospitalization defaults with values from not-yet-loaded data.
if (encounterClass) {
  if (["amb", "vr", "hh"].includes(encounterClass)) {
    newEncounter.hospitalization = {};
  } else if (
    HOSPITALIZATION_ENCOUNTER_CLASSES.includes(encounterClass) &&
    newEncounter.status === EncounterStatus.DISCHARGED
  ) {
    newEncounter.hospitalization = {
      ...newEncounter.hospitalization,
      discharge_disposition:
        newEncounter.hospitalization?.discharge_disposition ??
        careConfig.defaultDischargeDisposition,
    };
  } else {
    newEncounter.hospitalization = {
      ...newEncounter.hospitalization,
      discharge_disposition:
        encounterData?.hospitalization?.discharge_disposition,
    };
  }
}
